const hair=(kind,color)=>kind==='mira'||kind==='girl'?`<path d="M33 63Q19 28 49 18Q83 8 89 46L91 93H75L70 49L39 48L39 94H24Z" fill="${color}"/><path d="M30 65l-4 33m53-33l7 33" stroke="${color}" stroke-width="12" stroke-linecap="round"/>`:kind==='rowan'||kind==='boy'?`<path d="M30 56Q14 23 44 21Q60 7 77 25Q99 25 86 58L74 37L38 44Z" fill="${color}"/><g fill="${color}"><circle cx="35" cy="29" r="12"/><circle cx="52" cy="23" r="12"/><circle cx="70" cy="27" r="12"/><circle cx="81" cy="36" r="10"/></g>`:`<path d="M27 58Q13 31 39 25Q58 6 78 28Q100 37 83 65L75 40L59 48L42 40L34 65Z" fill="${color}"/>`;
export function portrait(id,small=false){
 const guide=guides.find(g=>g.id===id),avatar=avatars.find(a=>a.id===id);
 const kind=guide?.id||avatar?.kind||'neutral',skin=avatar?.skin||({mira:'#b87956',rowan:'#dba47e',ari:'#efc4a3'}[id]||'#efc4a3'),h=avatar?.hair||({mira:'#302a27',rowan:'#352f29',ari:'#6b4030'}[id]||'#392c28'),coat=guide?.color||avatar?.coat||'#abc4da';
 return `<svg viewBox="0 0 116 136" class="portrait ${small?'portrait-small':''}" aria-hidden="true"><path d="M7 135V59Q7 4 58 4Q109 4 109 59V135Z" fill="#eaf4ef"/>${hair(kind,h)}<path d="M16 136v-20q3-28 29-29h26q28 1 30 29v20" fill="${coat}"/><path d="M48 83v15q10 12 20 0V83" fill="${skin}"/><ellipse cx="58" cy="61" rx="27" ry="32" fill="${skin}"/><path d="M30 54Q29 23 54 22Q78 18 85 49Q70 43 64 33Q53 49 30 54" fill="${h}"/><g fill="#183430"><circle cx="47" cy="63" r="2"/><circle cx="70" cy="63" r="2"/></g><path d="M52 77q7 6 14-1" stroke="#7b493b" fill="none" stroke-width="2" stroke-linecap="round"/><path d="M56 68l-2 4h5" fill="none" stroke="#a26848" stroke-width="1.5"/><path d="M45 105l13 9 13-9" fill="none" stroke="#183f39" stroke-width="2"/><rect x="76" y="106" width="14" height="19" rx="2" fill="#fbfcfa" transform="rotate(8 83 116)"/><path d="M80 112h5m-5 5h5" stroke="#397958" stroke-width="1.5"/></svg>`;
}
function leaf(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><path d="M0 25Q-25-10 0-35Q26-10 0 25" fill="#75a183"/><path d="M0 25v-47" stroke="#397958" stroke-width="2"/></g>`;}
